const a=[{question:"JavaScript mein 'this' keyword kya hota hai?",options:["Current context ka reference — jis object pe call hua uska reference","Function ka naam","Variable ka value","Class ka naam"],correctIndex:0,explanation:"'this' hamesha current execution context ka reference hota hai. Object method mein = woh object. Global mein = window (browser). Arrow function mein = enclosing scope ka this."},{question:"call(), apply(), bind() mein kya farq hai?",options:["Call/Apply turant call karte hain (apply array leta hai), bind naya function deta hai","Dono same hain","Call slow hai, apply fast","Bind turant call karta hai"],correctIndex:0,explanation:"call() — arguments individually pass karte hain, turant execute hota hai. apply() — arguments array mein, turant execute. bind() — naya function return karta hai jo baad mein call kar sakte ho."},{question:"Prototype chain kya hoti hai?",options:["Jab property nahi milti toh JavaScript upar prototype mein dekhta hai","Array ki chain","Function ki chain","Variable ki chain"],correctIndex:0,explanation:"JavaScript property access mein pehle object pe dekhta hai, nahi mili toh prototype pe, phir uska prototype — chain chalti rehti hai Object.prototype tak. Isse inheritance hota hai."},{question:"Arrow function mein 'this' kya hota hai?",options:["Enclosing scope ka this — lexical this","Window object","Naya this har baar","Object jispe call hua"],correctIndex:0,explanation:"Arrow function ka apna this nahi hota — parent scope se 'this' leta hai (lexical scoping). Isliye object methods mein arrow function avoid karo — this galat milega."},{question:"Object.create() kya karta hai?",options:["Naya object banata hai specified prototype ke saath","Naya array banata hai","Naya function banata hai","String convert karta hai"],correctIndex:0,explanation:"Object.create(prototype) se naya object banta hai jo diye gaye prototype se inherit karta hai. Prototype chain manually set kar sakte ho — pure prototypal inheritance."}];export{a as default};
